namespace Wavelength.Playback.Contracts;

/// <summary>
/// A play report from the client. <c>PlayId</c> is generated by the client once per listen and reused on
/// every report and retry for that listen. <c>ListenedSeconds</c> is time actually listened, not position.
/// </summary>
public sealed record PlayEventRequest(string? PlayId, string? TrackId, int? ListenedSeconds, string? Reason);

/// <summary><c>Counted</c>: this play has been counted for royalties. <c>CountedNow</c>: by this very report.</summary>
public sealed record PlayEventResponse(Guid PlayId, string TrackId, int ListenedSeconds, bool Counted, bool CountedNow);
